-- Postcheck 328 (solo lectura, UNA consulta; columna estado por control). Esperado: todo OK.
select n, control, actual, esperado, case when ok then 'OK' else 'FALLA' end as estado
from (
  select 1 as n, 'las 3 tablas existen con RLS activa' as control,
         (select count(*) from pg_class where relnamespace = 'public'::regnamespace and relname in ('solicitudes_proveedor', 'solicitud_proveedor_eventos', 'solicitud_proveedor_avisos') and relrowsecurity)::text as actual, '3' as esperado,
         (select count(*) from pg_class where relnamespace = 'public'::regnamespace and relname in ('solicitudes_proveedor', 'solicitud_proveedor_eventos', 'solicitud_proveedor_avisos') and relrowsecurity) = 3 as ok
  union all select 2, 'anon sin ningún privilegio sobre las 3 tablas', (select count(*) from information_schema.role_table_grants where table_schema = 'public' and table_name in ('solicitudes_proveedor', 'solicitud_proveedor_eventos', 'solicitud_proveedor_avisos') and grantee = 'anon')::text, '0',
         (select count(*) from information_schema.role_table_grants where table_schema = 'public' and table_name in ('solicitudes_proveedor', 'solicitud_proveedor_eventos', 'solicitud_proveedor_avisos') and grantee = 'anon') = 0
  union all select 3, 'authenticated NO puede escribir solicitudes ni eventos (solo select)', (select count(*) from information_schema.role_table_grants where table_schema = 'public' and table_name in ('solicitudes_proveedor', 'solicitud_proveedor_eventos') and grantee = 'authenticated' and privilege_type <> 'SELECT')::text, '0',
         (select count(*) from information_schema.role_table_grants where table_schema = 'public' and table_name in ('solicitudes_proveedor', 'solicitud_proveedor_eventos') and grantee = 'authenticated' and privilege_type <> 'SELECT') = 0
  union all select 4, 'la RPC de eventos solo la ejecuta service_role', (select count(*) from information_schema.routine_privileges where routine_schema = 'public' and routine_name = 'registrar_evento_solicitud_proveedor' and grantee in ('anon', 'authenticated', 'PUBLIC'))::text, '0',
         (select count(*) from information_schema.routine_privileges where routine_schema = 'public' and routine_name = 'registrar_evento_solicitud_proveedor' and grantee in ('anon', 'authenticated', 'PUBLIC')) = 0
  union all select 5, 'unicidad: clave_envio, token_respuesta y (solicitud, tipo, dedupe) y (evento, usuario)',
         (select count(*) from pg_constraint where conrelid in ('public.solicitudes_proveedor'::regclass, 'public.solicitud_proveedor_eventos'::regclass, 'public.solicitud_proveedor_avisos'::regclass) and contype = 'u')::text, '4',
         (select count(*) from pg_constraint where conrelid in ('public.solicitudes_proveedor'::regclass, 'public.solicitud_proveedor_eventos'::regclass, 'public.solicitud_proveedor_avisos'::regclass) and contype = 'u') = 4
  union all select 6, 'identidad: solicitudes_proveedor clasificada (estricto) y con su guarda instalada', (select count(*) from public.contrato_guardas_config g where g.tabla = 'solicitudes_proveedor' and g.modo = 'estricto')::text || ' fila(s), '
         || (select count(*) from pg_trigger t where t.tgrelid = 'public.solicitudes_proveedor'::regclass and t.tgname = 'trg_contrato_guarda' and not t.tgisinternal)::text || ' guarda(s)', '1 fila(s), 1 guarda(s)',
         (select count(*) from public.contrato_guardas_config g where g.tabla = 'solicitudes_proveedor' and g.modo = 'estricto') = 1 and (select count(*) from pg_trigger t where t.tgrelid = 'public.solicitudes_proveedor'::regclass and t.tgname = 'trg_contrato_guarda' and not t.tgisinternal) = 1
  union all select 7, 'identidad: el instalador no tiene tablas de contrato sin clasificar (0 esperado)', (select count(*) from pg_class c join pg_namespace s on s.oid = c.relnamespace and s.nspname = 'public'
          where c.relkind in ('r', 'p') and (exists (select 1 from pg_attribute a where a.attrelid = c.oid and a.attnum > 0 and not a.attisdropped and a.attname in ('numero_contrato', 'contrato_numero'))
            or exists (select 1 from pg_constraint k where k.conrelid = c.oid and k.contype = 'f' and k.confrelid = 'public.ventas'::regclass) or c.relname = 'ventas')
            and not exists (select 1 from public.contrato_guardas_config g where g.tabla = c.relname::text))::text, '0',
         not exists (select 1 from pg_class c join pg_namespace s on s.oid = c.relnamespace and s.nspname = 'public'
          where c.relkind in ('r', 'p') and (exists (select 1 from pg_attribute a where a.attrelid = c.oid and a.attnum > 0 and not a.attisdropped and a.attname in ('numero_contrato', 'contrato_numero'))
            or exists (select 1 from pg_constraint k where k.conrelid = c.oid and k.contype = 'f' and k.confrelid = 'public.ventas'::regclass) or c.relname = 'ventas')
            and not exists (select 1 from public.contrato_guardas_config g where g.tabla = c.relname::text))
  union all select 8, 'catálogo de códigos de promoción: tabla con RLS, sin acceso anon, escritura solo vía RLS de producto', (select count(*) from pg_class where relnamespace = 'public'::regnamespace and relname = 'hotel_codigos_promocion' and relrowsecurity)::text || ' tabla(s) con RLS, anon=' || (select count(*) from information_schema.role_table_grants where table_schema = 'public' and table_name = 'hotel_codigos_promocion' and grantee = 'anon')::text, '1 tabla(s) con RLS, anon=0',
         (select count(*) from pg_class where relnamespace = 'public'::regnamespace and relname = 'hotel_codigos_promocion' and relrowsecurity) = 1 and (select count(*) from information_schema.role_table_grants where table_schema = 'public' and table_name = 'hotel_codigos_promocion' and grantee = 'anon') = 0
  union all select 9, 'disparadores y funciones de la 328 presentes (uid, código de solicitud, coherencia del código, eventos, reclamo)', (select count(*) from pg_trigger t where not t.tgisinternal and t.tgname in ('trg_solicitud_proveedor_uid', 'trg_solicitud_proveedor_codigo', 'trg_codigo_promocion_coherente'))::text || ' disparadores, ' || (select count(*) from pg_proc where pronamespace = 'public'::regnamespace and proname in ('registrar_evento_solicitud_proveedor', 'reclamar_envio_solicitud_proveedor', 'fn_solicitud_proveedor_uid', 'fn_solicitud_proveedor_codigo', 'fn_codigo_promocion_coherente', 'solicitud_proveedor_rango'))::text || ' funciones', '3 disparadores, 6 funciones',
         (select count(*) from pg_trigger t where not t.tgisinternal and t.tgname in ('trg_solicitud_proveedor_uid', 'trg_solicitud_proveedor_codigo', 'trg_codigo_promocion_coherente')) = 3 and (select count(*) from pg_proc where pronamespace = 'public'::regnamespace and proname in ('registrar_evento_solicitud_proveedor', 'reclamar_envio_solicitud_proveedor', 'fn_solicitud_proveedor_uid', 'fn_solicitud_proveedor_codigo', 'fn_codigo_promocion_coherente', 'solicitud_proveedor_rango')) = 6
  union all select 10, 'columnas de reintento seguro: payload (mensaje congelado) y ambiguo', (select count(*) from information_schema.columns where table_schema = 'public' and table_name = 'solicitudes_proveedor' and column_name in ('payload', 'ambiguo', 'tipo', 'contrato_uid', 'envio_iniciado_en', 'intentos', 'snapshot'))::text, '7',
         (select count(*) from information_schema.columns where table_schema = 'public' and table_name = 'solicitudes_proveedor' and column_name in ('payload', 'ambiguo', 'tipo', 'contrato_uid', 'envio_iniciado_en', 'intentos', 'snapshot')) = 7
  union all select 11, 'la reclamación y los eventos solo los ejecuta service_role (reclamar_envio_…)', (select count(*) from information_schema.routine_privileges where routine_schema = 'public' and routine_name = 'reclamar_envio_solicitud_proveedor' and grantee in ('anon', 'authenticated', 'PUBLIC'))::text, '0',
         (select count(*) from information_schema.routine_privileges where routine_schema = 'public' and routine_name = 'reclamar_envio_solicitud_proveedor' and grantee in ('anon', 'authenticated', 'PUBLIC')) = 0
  union all select 12, 'sin datos al aplicar (nada se envía ni se siembra): informativo', (select count(*) from public.solicitudes_proveedor)::text, '0 la primera vez', true
) q order by n;
